PRAC=[('起点代码（与上面相同）。','cat > order.py <<\'EOF\'\nSTOCK = {"pen": 20, "ink": 2, "pad": 0}\nPRICES = {"pen": 12.5, "ink": 30.0, "pad": 8.0}\nCOUPONS = {"SAVE10": 10}\nSENT = []\n\ndef process_order(d, flag):\n    # 检查\n    if not d.get("items"):\n        return None\n    t = 0\n    for i in d["items"]:\n        s, q = i.split(":")\n        q = int(q)\n        if s not in PRICES:\n            return -1\n        if STOCK[s] < q:\n            return -2\n        t += PRICES[s] * q\n    # 折扣\n    if d.get("type") == 2 and t > 200:\n        t = t * 0.95\n    c = d.get("coupon")\n    if c:\n        if c in COUPONS:\n            t = t - COUPONS[c]\n    if t < 0:\n        t = 0\n    # 扣库存\n    for i in d["items"]:\n        s, q = i.split(":")\n        STOCK[s] -= int(q)\n    # 通知\n    if flag:\n        SENT.append((d["email"], "订单金额 %.2f" % t))\n    return round(t, 2)\nEOF\ncp order.py order_before.py',''),
('安全网：特征测试。每个测试前重置全局状态（遗留代码的现实）。','cat > test_characterization.py <<\'EOF\'\nimport importlib, unittest\nimport order\n\nclass Characterization(unittest.TestCase):\n    def setUp(self):\n        importlib.reload(order)\n\n    def run_order(self, **d):\n        d.setdefault("email", "a@x.com")\n        return order.process_order(d, True)\n\n    def test_simple(self):\n        self.assertEqual(self.run_order(items=["pen:2"]), 25.0)\n\n    def test_vip_discount_above_200(self):\n        self.assertEqual(self.run_order(items=["pen:12", "ink:2"], type=2), 199.5)\n\n    def test_coupon(self):\n        self.assertEqual(self.run_order(items=["pen:1"], coupon="SAVE10"), 2.5)\n\n    def test_coupon_never_negative(self):\n        self.assertEqual(self.run_order(items=["pad:0"], coupon="SAVE10"), 0)\n\n    def test_unknown_sku_currently_returns_minus_1(self):\n        self.assertEqual(self.run_order(items=["cap:1"]), -1)\n\n    def test_out_of_stock_currently_returns_minus_2(self):\n        self.assertEqual(self.run_order(items=["ink:3"]), -2)\n\n    def test_empty_currently_returns_none(self):\n        self.assertIsNone(self.run_order(items=[]))\n\n    def test_stock_is_reduced_and_email_sent(self):\n        self.run_order(items=["ink:2"])\n        self.assertEqual(order.STOCK["ink"], 0)\n        self.assertEqual(order.SENT, [("a@x.com", "订单金额 60.00")])\n\nif __name__ == "__main__":\n    unittest.main(argv=["x"], verbosity=1)\nEOF\npython3 test_characterization.py',None),
('新接口的终态对照：领域对象、拆分阶段、异常、策略与注入。实际修改时应分成小提交；先做结构变换，再单独审查返回码→异常、Decimal 舍入与数量/库存规则的变更。下面的旧特征测试仍针对 order.py，下一步才测试 order_after.py；不能把两者混为同一套安全网。','cat > order_after.py <<\'EOF\'\nfrom dataclasses import dataclass\nfrom decimal import Decimal, ROUND_HALF_UP\nfrom enum import Enum\nfrom typing import Protocol\n\n\n@dataclass(frozen=True, order=True)\nclass Money:\n    amount: Decimal\n\n    @classmethod\n    def of(cls, value):\n        return cls(Decimal(str(value)).quantize(Decimal("0.01"), ROUND_HALF_UP))\n\n    def __add__(self, other): return Money.of(self.amount + other.amount)\n    def __sub__(self, other): return Money.of(max(self.amount - other.amount, Decimal(0)))\n    def times(self, factor): return Money.of(self.amount * Decimal(str(factor)))\n\nZERO = Money.of(0)\n\n\nclass OrderError(Exception): pass\nclass EmptyOrder(OrderError): pass\nclass UnknownProduct(OrderError): pass\nclass OutOfStock(OrderError): pass\nclass InvalidQuantity(OrderError): pass\n\n\nclass CustomerType(Enum):\n    REGULAR = 1\n    VIP = 2\n\n\n@dataclass(frozen=True)\nclass OrderLine:\n    sku: str\n    quantity: int\n\n\n@dataclass(frozen=True)\nclass OrderRequest:\n    lines: tuple\n    email: str\n    customer_type: CustomerType = CustomerType.REGULAR\n    coupon: str | None = None\n\n\n@dataclass(frozen=True)\nclass Quote:\n    request: OrderRequest\n    subtotal: Money\n    discount: Money\n\n    @property\n    def total(self):\n        return self.subtotal - self.discount\n\n\nclass Discount(Protocol):\n    def amount(self, request: OrderRequest, subtotal: Money) -> Money: ...\n\n\nVIP_DISCOUNT_MIN = Money.of(200)\nVIP_PAYABLE_RATE = Decimal("0.95")\n\nclass VipDiscount:\n    def amount(self, request, subtotal):\n        if request.customer_type is CustomerType.VIP and subtotal > VIP_DISCOUNT_MIN:\n            return subtotal - subtotal.times(VIP_PAYABLE_RATE)\n        return ZERO\n\n\nclass CouponDiscount:\n    def __init__(self, coupons):\n        self._coupons = coupons\n\n    def amount(self, request, subtotal):\n        return self._coupons.get(request.coupon, ZERO)\n\n\ndef parse_request(data):\n    lines = []\n    for item in data.get("items") or []:\n        sku, qty = item.split(":")\n        try:\n            quantity = int(qty)\n        except ValueError as e:\n            raise InvalidQuantity(f"{sku}: 数量必须为正整数") from e\n        if quantity <= 0:\n            raise InvalidQuantity(f"{sku}: 数量必须为正整数")\n        lines.append(OrderLine(sku, quantity))\n    if not lines:\n        raise EmptyOrder()\n    return OrderRequest(tuple(lines), data["email"], CustomerType(data.get("type", 1)), data.get("coupon"))\n\n\ndef price(request, catalog, discounts):\n    subtotal = ZERO\n    for line in request.lines:\n        if line.sku not in catalog:\n            raise UnknownProduct(line.sku)\n        subtotal = subtotal + catalog[line.sku].times(line.quantity)\n    after_vip = subtotal - VipDiscount().amount(request, subtotal)\n    discount = (subtotal - after_vip) + sum((d.amount(request, after_vip) for d in discounts), ZERO)\n    return Quote(request, subtotal, discount)\n\n\ndef place(quote, stock, notify):\n    total = quote.total\n    required = {}\n    for line in quote.request.lines:\n        required[line.sku] = required.get(line.sku, 0) + line.quantity\n    for sku, quantity in required.items():\n        if stock[sku] < quantity:\n            raise OutOfStock(f"{sku}: 需要 {quantity}，库存 {stock[sku]}")\n    for sku, quantity in required.items():\n        stock[sku] -= quantity\n    notify(quote.request.email, f"订单金额 {total.amount:.2f}")\n    return total\n\n\ndef process_order(data, *, catalog, stock, discounts, notify):\n    request = parse_request(data)\n    quote = price(request, catalog, discounts)\n    return place(quote, stock, notify)\nEOF\npython3 -c "import ast; ast.parse(open(\'order_after.py\').read()); print(\'ok\')"',None),
('在新接口上对应测试旧场景，并增加有意修正的边界：重复SKU按合计数量检查、拒绝非正整数数量、VIP按应付金额舍入。新接口返回 Money、以领域异常拒绝订单；Decimal 的 ROUND_HALF_UP 与旧 float/round 不在所有输入上等价，旧调用方需要适配或明确迁移。库存与通知之间没有事务：通知失败时库存已扣减，生产系统还需持久化订单、幂等和 Outbox 等设计，不能整单盲目重试。','cat > test_order.py <<\'EOF\'\nimport unittest\nfrom decimal import Decimal\nfrom order_after import *\n\nclass OrderTest(unittest.TestCase):\n    def setUp(self):\n        self.catalog = {"pen": Money.of(12.5), "ink": Money.of(30), "pad": Money.of(8)}\n        self.stock = {"pen": 20, "ink": 2, "pad": 0}\n        self.sent = []\n        self.discounts = [CouponDiscount({"SAVE10": Money.of(10)})]\n\n    def order(self, **data):\n        data.setdefault("email", "a@x.com")\n        return process_order(data, catalog=self.catalog, stock=self.stock,\n                             discounts=self.discounts, notify=lambda to, text: self.sent.append((to, text)))\n\n    def test_simple(self):\n        self.assertEqual(self.order(items=["pen:2"]), Money.of(25))\n\n    def test_vip_discount_above_200(self):\n        self.assertEqual(self.order(items=["pen:12", "ink:2"], type=2), Money.of(199.5))\n\n    def test_vip_rounds_payable_amount(self):\n        self.assertEqual(self.order(items=["pen:17"], type=2), Money.of(201.88))\n\n    def test_coupon(self):\n        self.assertEqual(self.order(items=["pen:1"], coupon="SAVE10"), Money.of(2.5))\n\n    def test_coupon_never_negative(self):\n        self.discounts = [CouponDiscount({"SAVE20": Money.of(20)})]\n        self.assertEqual(self.order(items=["pen:1"], coupon="SAVE20"), ZERO)\n\n    def test_unknown_product(self):\n        self.assertRaises(UnknownProduct, self.order, items=["cap:1"])\n\n    def test_out_of_stock_leaves_stock_untouched(self):\n        self.assertRaises(OutOfStock, self.order, items=["pen:1", "ink:3"])\n        self.assertEqual(self.stock["pen"], 20)\n\n    def test_repeated_sku_uses_total_quantity(self):\n        self.assertRaises(OutOfStock, self.order, items=["pen:15", "pen:15"])\n        self.assertEqual(self.stock["pen"], 20)\n        self.assertEqual(self.sent, [])\n\n    def test_invalid_quantity_leaves_stock_untouched(self):\n        for quantity in ["0", "-1", "bad"]:\n            with self.subTest(quantity=quantity):\n                self.assertRaises(InvalidQuantity, self.order, items=[f"pen:{quantity}"])\n                self.assertEqual(self.stock["pen"], 20)\n\n    def test_empty(self):\n        self.assertRaises(EmptyOrder, self.order, items=[])\n\n    def test_stock_is_reduced_and_email_sent(self):\n        self.order(items=["ink:2"])\n        self.assertEqual(self.stock["ink"], 0)\n        self.assertEqual(self.sent, [("a@x.com", "订单金额 60.00")])\n\nif __name__ == "__main__":\n    unittest.main(argv=["x"], verbosity=1)\nEOF\npython3 test_order.py',None),
('新需求：“满 300 减 30”。只新增一个类，并在组装处注册。','cat > threshold.py <<\'EOF\'\nfrom dataclasses import dataclass\nfrom order_after import Money, ZERO\n\n@dataclass(frozen=True)\nclass ThresholdDiscount:\n    minimum: Money\n    off: Money\n\n    def amount(self, request, subtotal):\n        return self.off if subtotal >= self.minimum else ZERO\nEOF\npython3 -c "\nfrom order_after import *\nfrom threshold import ThresholdDiscount\ndiscounts = [CouponDiscount({}), ThresholdDiscount(Money.of(300), Money.of(30))]\nstock = {\'pen\': 100}\nfor items in ([\'pen:20\'], [\'pen:30\']):\n    total = process_order({\'items\': items, \'email\': \'z@x.com\'}, catalog={\'pen\': Money.of(12.5)},\n                          stock=stock, discounts=discounts, notify=lambda *a: None)\n    print(items, total.amount)"',None),
('前后度量对比（用第 3 课的工具）。','cat > longest.py <<\'EOF\'\nimport ast, sys\nfor path in sys.argv[1:]:\n    tree = ast.parse(open(path).read())\n    fns = [(n.end_lineno - n.lineno + 1, n.name) for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]\n    longest = max(fns)\n    print(f"{path:<16} 函数 {len(fns):>2} 个，最长 {longest[0]:>2} 行（{longest[1]}）")\nEOF\npython3 longest.py order_before.py order_after.py; grep -c "return -\\|return None" order_before.py order_after.py',None)]
CHAL=('继续扩展','在整洁的结构上完成两个新需求，并说明各自修改了哪些地方：① 优惠券与 VIP 折扣不能叠加，取其中较大者；② 下单成功后除了邮件，还要写一条审计日志，业务拒绝的订单也要记录原因。',
'<ol><li><b>折扣互斥</b>：把“如何组合多个折扣”提取为一个策略，<code>price()</code> 接收 <code>combine</code>：<pre class="cmd">def best_of(discounts):\n    def combine(request, subtotal):\n        return max((d.amount(request, subtotal) for d in discounts), default=ZERO)\n    return combine</pre>修改点：<code>price()</code> 一处（改为调用 <code>combine</code>）+ 组装处。VipDiscount 也作为普通策略注册，不再写死在 <code>price()</code> 中——这是对第一次重构的进一步改进。为“同时满足两者时取较大者”写测试。</li><li><b>审计日志</b>：这是横切关注点，不应写进 <code>place()</code>。在组合根包装 <code>process_order</code>：<pre class="cmd">def audited(process, audit):\n    def run(data, **deps):\n        try:\n            total = process(data, **deps)\n        except OrderError as e:\n            audit("rejected", data, repr(e))\n            raise\n        audit("placed", data, total)\n        return total\n    return run</pre>修改点：只新增代码。<code>process_order</code> 本身与它的测试都没有改变。</li></ol>')
